-- 023: remove lessons from the live catalog without deleting historical facts.
-- Run via database/migrate.mjs; the inherited 005 invariant remains enforced.

-- @step lesson_soft_delete
-- @replaces-check 005_courses/create_course_lesson
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'course_lesson' AND TABLE_TYPE = 'BASE TABLE' AND ENGINE = 'InnoDB' AND TABLE_COLLATION = 'utf8mb4_0900_ai_ci') AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'course_lesson') = 11 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'course_lesson' AND ((COLUMN_NAME = 'id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND EXTRA = 'auto_increment') OR (COLUMN_NAME IN ('course_id', 'chapter_id') AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'title' AND COLUMN_TYPE = 'varchar(255)' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'lesson_type' AND COLUMN_TYPE = 'varchar(32)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'video') OR (COLUMN_NAME = 'is_required' AND COLUMN_TYPE = 'tinyint unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = '1') OR (COLUMN_NAME = 'sort_order' AND COLUMN_TYPE = 'int' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = '0') OR (COLUMN_NAME = 'current_version_id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES') OR (COLUMN_NAME = 'created_at' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)') OR (COLUMN_NAME = 'updated_at' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)' AND EXTRA = 'DEFAULT_GENERATED on update CURRENT_TIMESTAMP(3)') OR (COLUMN_NAME = 'deleted_at' AND DATA_TYPE = 'datetime' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL AND EXTRA = ''))) = 11 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'course_lesson') = 4 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'course_lesson' AND ((INDEX_NAME = 'PRIMARY' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_course_lesson_course' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'course_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_course_lesson_chapter_sort' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'chapter_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_course_lesson_chapter_sort' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'sort_order' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL))) = 4 THEN 1 ELSE 0 END AS complete;
ALTER TABLE `course_lesson` ADD COLUMN `deleted_at` DATETIME(3) NULL COMMENT '逻辑删除时间；版本、媒体引用和学习事实永久保留';
